<script setup lang="ts">
import {t} from "../i18n"
import { ref, watch } from 'vue'
import { useQuasar } from 'quasar'
import { useCms } from '../store'
import { api, send } from '../api'
import Icon from './Icon.vue'
import MediaLibrary from './MediaLibrary.vue'
const cms=useCms(),q=useQuasar(),selected=ref('Header'),saving=ref(false),picker=ref(false),error=ref('')
const values=ref<Record<string,any>>({})
const defaults=()=>({'Header':{enabled:true,title:cms.selected?.name||'',logo:'',text:''},'Footer':{enabled:true,text:'© '+new Date().getFullYear()+' '+cms.selected?.name+'. All rights reserved.'},'Announcement Bar':{enabled:false,text:'Something new is on its way.',button:'Learn more',link:'home'},'Global CTA':{enabled:false,title:'Let’s make something great.',text:'We would love to hear from you.',button:'Get in touch',link:'mailto:hello@example.com'}})
async function load(){error.value='';try{values.value=defaults();const rows=await api('/websites/'+cms.selectedId+'/components');for(const r of rows)if(r.name in values.value)values.value[r.name]={...values.value[r.name],...r.content}}catch(e:any){error.value=e.message}}
async function save(){saving.value=true;try{await api('/websites/'+cms.selectedId+'/components',send('POST',{name:selected.value,content:values.value[selected.value]}));q.notify({type:'positive',message:t('Global component saved. All public pages use the new version.')});await cms.load()}catch(e:any){q.notify({type:'negative',message:t(e.message)})}finally{saving.value=false}}
watch(()=>cms.selectedId,load,{immediate:true})
</script>
<template><div v-if="error" class="empty-state"><p>{{ error }}</p><button class="btn secondary" @click="load">{{ $t("Retry") }}</button></div><div v-else class="global-layout"><section class="panel"><h2>{{ $t("One change. Every page.") }}</h2><p class="muted">{{ $t("These components are rendered from shared settings, never copied into individual pages.") }}</p><div class="customizer-tabs"><button v-for="name in Object.keys(values)" :class="{active:selected===name}" @click="selected=name">{{ $t(name) }}</button></div><template v-if="values[selected]"><q-toggle v-if="['Announcement Bar','Global CTA'].includes(selected)" v-model="values[selected].enabled" :label="$t('Show on every page')"/><q-input v-if="['Header','Global CTA'].includes(selected)" outlined v-model="values[selected].title" :label="$t('Title / brand name')" maxlength="190"/><q-input outlined v-model="values[selected].text" :label="$t(selected==='Footer'?'Footer text':'Supporting text')" type="textarea" rows="3" maxlength="2000"/><template v-if="selected==='Header'"><label class="field-label">{{ $t("Brand logo") }}</label><button class="image-selector" @click="picker=true"><img v-if="values.Header.logo" :src="values.Header.logo"><Icon v-else name="ImagePlus" :size="24"/><span>{{ $t("Select logo from your media library") }}</span></button><button v-if="values.Header.logo" class="text-link" @click="values.Header.logo=''">{{ $t("Remove logo") }}</button></template><template v-if="['Announcement Bar','Global CTA'].includes(selected)"><q-input outlined v-model="values[selected].button" :label="$t('Link label')" maxlength="100"/><q-input outlined v-model="values[selected].link" :label="$t('Page slug or https:// / mailto: URL')" maxlength="2048"/></template><div class="dialog-footer"><span>{{ $t("Saved changes apply immediately.") }}</span><q-btn color="primary" unelevated :label="$t('Save global component')" :loading="saving" @click="save"/></div></template></section><aside class="panel global-preview"><span class="eyebrow">{{ $t("COMPONENT PREVIEW") }}</span><div v-if="values[selected]" class="global-preview-content"><template v-if="selected==='Header'"><img v-if="values.Header.logo" :src="values.Header.logo" class="global-logo"><h2>{{ values.Header.title }}</h2><p>{{ values.Header.text }}</p><span>Home &nbsp; · &nbsp; Our story &nbsp; · &nbsp; Contact</span></template><template v-else><span v-if="values[selected].enabled===false" class="status-pill draft">{{ $t("Currently hidden") }}</span><h2>{{ values[selected].title }}</h2><p>{{ values[selected].text }}</p><span v-if="values[selected].button" class="btn primary">{{ values[selected].button }}</span></template></div><div class="info-note"><Icon name="Languages"/><span>{{ $t("Translate text in Languages using keys such as") }} <code>{{ $t("components.Header.title") }}</code>, <code>{{ $t("components.Footer.text") }}</code>{{ $t(", or") }} <code>{{ $t("components.Global CTA.button") }}</code>{{ $t(". Matching translations replace only that field on the public website.") }}</span></div></aside></div><q-dialog v-model="picker"><q-card class="media-picker-dialog"><div class="dialog-heading"><h2>{{ $t("Choose your brand logo") }}</h2><button class="icon-btn" @click="picker=false"><Icon name="X"/></button></div><MediaLibrary :site-id="cms.selectedId!" picker @select="(m:any)=>{values.Header.logo=m.url;picker=false}"/></q-card></q-dialog></template>
